// The Life Lists copy (life-lists-tab FR-20, FR-27, FR-33, FR-34, FR-44; QA-35,
// QA-53). The FR-33 and FR-27 sentences are asserted as literals (the one
// content test); everything else is a rule swept over a corpus generated by
// calling every builder over every reachable state, so a new string joins the
// sweep by being added to the module (ui.md v1.0.5, testing.md v1.0.22).

import { describe, it, expect } from 'vitest'
import * as copy from './lifeListsCopy'
import { MEDIA_FORMATS, type MediaFormat, type MediaPresence } from './lifeLists'

const SELECTIONS: MediaFormat[][] = [[], ['Photo'], ['Audio'], ['Video'], ['Photo', 'Audio'], ['Photo', 'Video'], ['Audio', 'Video'], ['Photo', 'Audio', 'Video']]
const COUNTS = [0, 1, 2, 1204]
const PRESENCE: MediaPresence[] = [false, true].flatMap(photo => [false, true].flatMap(audio => [false, true].map(video => ({ photo, audio, video }))))

describe('the count sentence (FR-33, QA-35)', () => {
  it('renders the eight PRD sentences verbatim', () => {
    const s = (sel: MediaFormat[]) => copy.countSentence(1204, new Set(sel))
    expect(s([])).toBe('1,204 species, newest first by the date of your first sighting.')
    expect(s(['Photo'])).toBe('1,204 species with a photo, newest first by the date of your first photo.')
    expect(s(['Audio'])).toBe('1,204 species with audio, newest first by the date of your first audio recording.')
    expect(s(['Video'])).toBe('1,204 species with video, newest first by the date of your first video.')
    expect(s(['Photo', 'Audio'])).toBe('1,204 species with a photo and audio, newest first by the date each had both.')
    expect(s(['Photo', 'Video'])).toBe('1,204 species with a photo and video, newest first by the date each had both.')
    expect(s(['Audio', 'Video'])).toBe('1,204 species with audio and video, newest first by the date each had both.')
    expect(s(['Photo', 'Audio', 'Video'])).toBe('1,204 species with a photo, audio, and video, newest first by the date each had all three.')
  })

  it('follows the manifest order, not the order the buttons were pressed in', () => {
    expect(copy.countSentence(3, new Set<MediaFormat>(['Video', 'Photo']))).toBe(copy.countSentence(3, new Set<MediaFormat>(['Photo', 'Video'])))
  })

  it('splits as N plus the rest, and the parts are the sentence', () => {
    for (const sel of SELECTIONS) for (const n of COUNTS) for (const region of [null, 'Marin, CA']) {
      const p = copy.countSentenceParts(n, new Set(sel), region)
      expect(p.count).toBe(n.toLocaleString('en-US'))
      expect(p.region).toBe(region)
      expect(p.count + p.before + (p.region ?? '') + p.after).toBe(copy.countSentence(n, new Set(sel), region))
      // Unfiltered, the sentence is all in `before`, so the tab renders today's nodes.
      if (region === null) expect(p.after).toBe('')
    }
  })

  it('generates from the manifest: a hypothetical fourth format gets its own sentence with no new copy', () => {
    const order = [...MEDIA_FORMATS, 'Sketch'] as MediaFormat[]
    const table = { ...copy.FORMAT_COPY, Sketch: { label: 'Sketch', withNoun: 'a sketch', firstNoun: 'your first sketch', presenceNoun: 'sketch' } }
    const one = copy.countSentenceParts(2, new Set(['Sketch'] as unknown as MediaFormat[]), null, order, table)
    expect(one.count + one.before).toBe('2 species with a sketch, newest first by the date of your first sketch.')
    const all = copy.countSentenceParts(2, new Set(order), null, order, table)
    expect(all.count + all.before).toBe('2 species with a photo, audio, video, and a sketch, newest first by the date each had all 4.')
  })
})

describe('the region sentences (life-list-region-filter FR-19, FR-20, QA-19, QA-20)', () => {
  const R = 'Marin, CA'
  it('renders the regional templates verbatim', () => {
    const s = (sel: MediaFormat[]) => copy.countSentence(184, new Set(sel), R)
    expect(s([])).toBe('184 species in Marin, CA, newest first by the date of your first sighting there.')
    expect(s(['Photo'])).toBe('184 species with a photo in Marin, CA, newest first by the date of your first photo there.')
    expect(s(['Audio'])).toBe('184 species with audio in Marin, CA, newest first by the date of your first audio recording there.')
    expect(s(['Photo', 'Audio'])).toBe('184 species with a photo and audio in Marin, CA, newest first by the date each had both there.')
    expect(s(['Photo', 'Audio', 'Video'])).toBe('184 species with a photo, audio, and video in Marin, CA, newest first by the date each had all three there.')
    expect(copy.emptySentence(new Set(), R)).toBe('No countable species in Marin, CA yet.')
    expect(copy.emptySentence(new Set<MediaFormat>(['Video']), R)).toBe('No species matches this selection in Marin, CA yet.')
  })

  it('names the region exactly once in each of the eight regional sentences, and says "there"', () => {
    for (const sel of SELECTIONS) {
      const t = copy.countSentence(3, new Set(sel), R)
      expect(t.split(R).length - 1, t).toBe(1)
      expect(t.endsWith(' there.'), t).toBe(true)
      expect(copy.countSentence(3, new Set(sel))).not.toContain(' there.')
    }
  })

  it('the Region control copy', () => {
    expect([copy.REGION_CONTROL_LABEL, copy.EVERYWHERE_LABEL, copy.REGION_LIST_LABEL, copy.REGION_CHEVRON_LABEL, copy.REGION_NO_MATCH, copy.REGION_PLACEHOLDER])
      .toEqual(['Region', 'Everywhere', 'Regions in your backup', 'Show regions', 'No region matches this search.', 'Type a country, state, or county'])
    expect(copy.REGION_GROUP_LABELS).toEqual({ country: 'Countries', state: 'States and provinces', county: 'Counties' })
  })
})

describe('the fixed sentences (FR-20, FR-27, FR-34)', () => {
  it('renders the PRD sentences verbatim', () => {
    expect(copy.ML_NONE_SENTENCE).toBe('Photo, audio, and video life lists need your Macaulay Library export, saved in Settings under Default Files.')
    expect(copy.ML_UNREADABLE_SENTENCE).toBe("SnowRaven couldn't read your Macaulay Library export, so photo, audio, and video life lists are unavailable; re-upload it in Settings under Default Files.")
    expect(copy.STATUS_UNRESOLVED).toBe('Escapee and exotic status comes from the exotic status check on Statistics, which has not finished for this export, so species it has not settled are listed.')
    // ebird-store-hygiene: Include Exotics now starts on, so the sentence names
    // the one switch whose departure from its default makes the list shorter.
    expect(copy.STATUS_RESOLVED).toBe('Escapee and exotic status comes from the exotic status check on Statistics, so with Include Exotics off this list can be shorter than the Statistics species figure.')
    expect(copy.STATUS_RESOLVED).toContain(`with ${copy.SWITCH_LABELS.exotics} off`)
    expect(copy.emptySentence(new Set())).toBe('No countable species in your eBird backup yet.')
    expect(copy.emptySentence(new Set<MediaFormat>(['Audio', 'Video']))).toBe('No species matches this selection yet.')
    expect(copy.SETUP_BODY).toBe("The Life Lists tab loads automatically from your stored eBird backup. You haven't saved one yet.")
  })
})

describe('the media cell label (FR-44)', () => {
  it('names the present formats in the fixed order, or says there are none', () => {
    expect(copy.mediaLabel({ photo: true, audio: true, video: false })).toBe('Media: photo, audio')
    expect(copy.mediaLabel({ photo: false, audio: true, video: true })).toBe('Media: audio, video')
    expect(copy.mediaLabel({ photo: false, audio: false, video: false })).toBe('No media')
  })
})

describe('copy hygiene over the generated corpus (NFR-09, QA-53)', () => {
  const corpus: string[] = []
  for (const sel of SELECTIONS) for (const region of [null, 'Marin, CA']) {
    for (const n of COUNTS) corpus.push(copy.countSentence(n, new Set(sel), region))
    corpus.push(copy.emptySentence(new Set(sel), region))
  }
  for (const p of PRESENCE) corpus.push(copy.mediaLabel(p))
  for (const n of COUNTS) corpus.push(copy.showAllLabel(n), copy.showingLabel(n), copy.positionPrefix(n, 1204))
  corpus.push(
    copy.STATUS_UNRESOLVED, copy.STATUS_RESOLVED, copy.ML_NONE_SENTENCE, copy.ML_UNREADABLE_SENTENCE,
    copy.TAB_TITLE, copy.TAB_DESCRIPTION, copy.SETUP_TITLE, copy.SETUP_BODY, copy.LOADING_LABEL,
    copy.SWITCH_LABELS.escapees, copy.SWITCH_LABELS.exotics, copy.MEDIA_GROUP_LABEL, copy.SHOW_NEXT_LABEL,
    copy.NO_CHECKLIST_LABEL, ...MEDIA_FORMATS.map(f => copy.FORMAT_COPY[f].label),
    copy.REGION_CONTROL_LABEL, copy.EVERYWHERE_LABEL, copy.REGION_LIST_LABEL, copy.REGION_CHEVRON_LABEL,
    copy.REGION_NO_MATCH, copy.REGION_PLACEHOLDER, ...Object.values(copy.REGION_GROUP_LABELS),
  )

  it('holds no em dash anywhere', () => {
    expect(corpus.filter(s => s.includes('\u2014'))).toEqual([])
    expect(corpus.length).toBeGreaterThan(60)
  })

  it('uses the serial comma wherever three items are listed', () => {
    for (const s of corpus) if (/photo, audio,? (and|or) video/.test(s)) expect(s, s).toMatch(/photo, audio, (and|or) video/)
    expect(corpus.filter(s => s.includes('photo, audio, and video')).length).toBeGreaterThan(2)
  })

  it('no count of one takes a plural noun other than "species", which is its own plural', () => {
    expect(corpus.filter(s => /\b1 (?!species\b)[a-z]+s\b/.test(s))).toEqual([])
  })
})
